import 'package:flutter/material.dart';

import 'app_typography.dart';
import 'hybrid_tokens.dart';

/// Central geometry presets retained from the adopted production composition.
/// Widgets choose a preset; they never specify numeric text geometry.
enum AppTextGeometry {
  compact,
  badge,
  standard,
  supporting,
  reading,
  emptyState,
  launchFailure,
  spacedLabel,
  fitValue,
  fitMeasure,
  fitVerdict,
  fitExplanation,
  calendarCell,
  calendarCaption,
  explanatory,
  tableValue,
  timelineDate,
  summaryTitle,
  compactHeading,
  weatherDescription,
  answer,
  contextCaption,
  formLabel,
  answerNeutralTracking,
  chartLabel,
  calendarHeading,
  calendarInstruction,
  moonTotal,
  resultNotes,
  tightTracking,
  recoveryBody,
  chartCaption,
  candidateTitle,
  dialogTitle,
}

/// Typed typography roles and inherited-style geometry installed in ThemeData.
/// Base definitions stay in AppTypography; this extension is the runtime reader.
@immutable
class AppTextTheme extends ThemeExtension<AppTextTheme> {
  const AppTextTheme._(this._roles, this._geometry);
  final Map<String, TextStyle> _roles;
  final Map<AppTextGeometry, TextStyle> _geometry;

  static AppTextTheme of(BuildContext context) =>
      Theme.of(context).extension<AppTextTheme>() ?? standard;

  static final standard = AppTextTheme._(
    {
      "support": AppTypography.support,
      "nightHeading": AppTypography.nightHeading,
      "answerHeading": AppTypography.answerHeading,
      "screenTitle": AppTypography.screenTitle,
      "sectionHeading": AppTypography.sectionHeading,
      "sectionSubject": AppTypography.sectionSubject,
      "itemTitle": AppTypography.itemTitle,
      "rowTitle": AppTypography.rowTitle,
      "value": AppTypography.value,
      "body": AppTypography.body,
      "caption": AppTypography.caption,
      "dense": AppTypography.dense,
      "navigationLabel": AppTypography.navigationLabel,
      "homeHeading": AppTypography.homeHeading,
      "homePlanHeading": AppTypography.homePlanHeading,
      "homeTarget": AppTypography.homeTarget,
      "homeWordmark": AppTypography.homeWordmark,
      "homeWelcome": AppTypography.homeWelcome,
      "inherited": const TextStyle(),
    },
    {
      AppTextGeometry.compact: TextStyle(height: 1.4),
      AppTextGeometry.badge: TextStyle(height: 1.4, letterSpacing: 0),
      AppTextGeometry.standard: TextStyle(height: 1.5),
      AppTextGeometry.supporting: TextStyle(height: 1.55),
      AppTextGeometry.reading: TextStyle(height: 1.6),
      AppTextGeometry.emptyState: TextStyle(height: 22.1 / 13),
      AppTextGeometry.launchFailure: TextStyle(fontSize: 16, height: 1.4),
      AppTextGeometry.spacedLabel: TextStyle(letterSpacing: 0.5),
      AppTextGeometry.fitValue: TextStyle(fontSize: 15, height: 19 / 15),
      AppTextGeometry.fitMeasure: TextStyle(fontSize: 13, height: 17 / 13),
      AppTextGeometry.fitVerdict: TextStyle(fontSize: 13, height: 1.5),
      AppTextGeometry.fitExplanation: TextStyle(fontSize: 14, height: 1.55),
      AppTextGeometry.calendarCell: TextStyle(fontSize: 12, height: 1.5),
      AppTextGeometry.calendarCaption: TextStyle(
        fontSize: HybridTokens.calendarCaptionSize,
      ),
      AppTextGeometry.explanatory: TextStyle(height: 1.65),
      AppTextGeometry.tableValue: TextStyle(height: 1.45),
      AppTextGeometry.timelineDate: TextStyle(height: 17 / 13),
      AppTextGeometry.summaryTitle: TextStyle(fontSize: 18),
      AppTextGeometry.compactHeading: TextStyle(
        height: 1.4,
        letterSpacing: -0.33,
      ),
      AppTextGeometry.weatherDescription: TextStyle(height: 1.7),
      AppTextGeometry.answer: TextStyle(height: 1.3),
      AppTextGeometry.contextCaption: TextStyle(fontSize: 13),
      AppTextGeometry.formLabel: TextStyle(fontSize: 14),
      AppTextGeometry.answerNeutralTracking: TextStyle(
        height: 1.3,
        letterSpacing: 0,
      ),
      AppTextGeometry.chartLabel: TextStyle(
        fontFamily: HybridTokens.fontFamily,
        fontSize: HybridTokens.chartLabelSize,
      ),
      AppTextGeometry.calendarHeading: TextStyle(
        height: 1.35,
        letterSpacing: -0.33,
      ),
      AppTextGeometry.calendarInstruction: TextStyle(height: 24 / 13),
      AppTextGeometry.moonTotal: TextStyle(fontSize: 24, height: 1.3),
      AppTextGeometry.resultNotes: TextStyle(fontSize: 16, height: 1.5),
      AppTextGeometry.tightTracking: TextStyle(letterSpacing: -0.25),
      AppTextGeometry.recoveryBody: TextStyle(fontSize: 16),
      AppTextGeometry.chartCaption: TextStyle(height: 16 / 12),
      AppTextGeometry.candidateTitle: TextStyle(fontSize: 23, height: 1.3),
      AppTextGeometry.dialogTitle: TextStyle(height: 21 / 16),
    },
  );

  TextStyle get support => _roles["support"]!;
  TextStyle get nightHeading => _roles["nightHeading"]!;
  TextStyle get answerHeading => _roles["answerHeading"]!;
  TextStyle get screenTitle => _roles["screenTitle"]!;
  TextStyle get sectionHeading => _roles["sectionHeading"]!;
  TextStyle get sectionSubject => _roles["sectionSubject"]!;
  TextStyle get itemTitle => _roles["itemTitle"]!;
  TextStyle get rowTitle => _roles["rowTitle"]!;
  TextStyle get value => _roles["value"]!;
  TextStyle get body => _roles["body"]!;
  TextStyle get caption => _roles["caption"]!;
  TextStyle get dense => _roles["dense"]!;
  TextStyle get navigationLabel => _roles["navigationLabel"]!;
  TextStyle get homeHeading => _roles["homeHeading"]!;
  TextStyle get homePlanHeading => _roles["homePlanHeading"]!;
  TextStyle get homeTarget => _roles["homeTarget"]!;
  TextStyle get homeWordmark => _roles["homeWordmark"]!;
  TextStyle get homeWelcome => _roles["homeWelcome"]!;
  TextStyle get inherited => _roles["inherited"]!;

  /// Retains the caller's inherited family/color/weight and replaces only the
  /// centrally declared geometry. A null Material role stays inherited.
  TextStyle resolve(TextStyle? base, AppTextGeometry geometry) =>
      (base ?? inherited).merge(_geometry[geometry]);

  @override
  AppTextTheme copyWith({
    TextStyle? support,
    TextStyle? nightHeading,
    TextStyle? answerHeading,
    TextStyle? screenTitle,
    TextStyle? sectionHeading,
    TextStyle? sectionSubject,
    TextStyle? itemTitle,
    TextStyle? rowTitle,
    TextStyle? value,
    TextStyle? body,
    TextStyle? caption,
    TextStyle? dense,
    TextStyle? navigationLabel,
    TextStyle? homeHeading,
    TextStyle? homePlanHeading,
    TextStyle? homeTarget,
    TextStyle? homeWordmark,
    TextStyle? homeWelcome,
    TextStyle? inherited,
    Map<AppTextGeometry, TextStyle>? geometry,
  }) => AppTextTheme._(
    {
      'support': support ?? this.support,
      'nightHeading': nightHeading ?? this.nightHeading,
      'answerHeading': answerHeading ?? this.answerHeading,
      'screenTitle': screenTitle ?? this.screenTitle,
      'sectionHeading': sectionHeading ?? this.sectionHeading,
      'sectionSubject': sectionSubject ?? this.sectionSubject,
      'itemTitle': itemTitle ?? this.itemTitle,
      'rowTitle': rowTitle ?? this.rowTitle,
      'value': value ?? this.value,
      'body': body ?? this.body,
      'caption': caption ?? this.caption,
      'dense': dense ?? this.dense,
      'navigationLabel': navigationLabel ?? this.navigationLabel,
      'homeHeading': homeHeading ?? this.homeHeading,
      'homePlanHeading': homePlanHeading ?? this.homePlanHeading,
      'homeTarget': homeTarget ?? this.homeTarget,
      'homeWordmark': homeWordmark ?? this.homeWordmark,
      'homeWelcome': homeWelcome ?? this.homeWelcome,
      'inherited': inherited ?? this.inherited,
    },
    {..._geometry, ...?geometry},
  );

  @override
  AppTextTheme lerp(covariant AppTextTheme? other, double t) {
    if (other == null) return this;
    return AppTextTheme._(
      {
        for (final key in _roles.keys)
          key: TextStyle.lerp(_roles[key], other._roles[key], t)!,
      },
      {
        for (final key in _geometry.keys)
          key: TextStyle.lerp(_geometry[key], other._geometry[key], t)!,
      },
    );
  }
}

// Generated by tool/culmina_mark.py; edit the tool, not this file.
import 'package:flutter/material.dart';

/// The mark's colours on one of the app's surfaces; [glint] and
/// [starPeak] are the launch gesture's accents.
final class CulminaMarkColors extends ThemeExtension<CulminaMarkColors> {
  const CulminaMarkColors({
    required this.background,
    required this.orbit,
    required this.inner,
    required this.star,
    required this.glint,
    required this.starPeak,
  });

  final Color background;
  final Color orbit;
  final Color inner;
  final Color star;
  final Color glint;
  final Color starPeak;

  static CulminaMarkColors of(BuildContext context) =>
      Theme.of(context).extension<CulminaMarkColors>() ??
      (Theme.of(context).brightness == Brightness.dark ? dark : light);

  @override
  CulminaMarkColors copyWith({
    Color? background,
    Color? orbit,
    Color? inner,
    Color? star,
    Color? glint,
    Color? starPeak,
  }) => CulminaMarkColors(
    background: background ?? this.background,
    orbit: orbit ?? this.orbit,
    inner: inner ?? this.inner,
    star: star ?? this.star,
    glint: glint ?? this.glint,
    starPeak: starPeak ?? this.starPeak,
  );

  @override
  CulminaMarkColors lerp(CulminaMarkColors? other, double t) {
    if (other == null || t == 0) return this;
    if (t == 1) return other;
    return CulminaMarkColors(
      background: Color.lerp(background, other.background, t)!,
      orbit: Color.lerp(orbit, other.orbit, t)!,
      inner: Color.lerp(inner, other.inner, t)!,
      star: Color.lerp(star, other.star, t)!,
      glint: Color.lerp(glint, other.glint, t)!,
      starPeak: Color.lerp(starPeak, other.starPeak, t)!,
    );
  }

  static const light = CulminaMarkColors(
    background: Color(0xFFFFFFFF),
    orbit: Color(0xFF0F1C4D),
    inner: Color(0xFF6C7FB8),
    star: Color(0xFF1F7FE5),
    glint: Color(0xFF1F7FE5),
    starPeak: Color(0xFF0B5CBF),
  );

  static const dark = CulminaMarkColors(
    background: Color(0xFF191919),
    orbit: Color(0xFFF5F7FD),
    inner: Color(0xFFA4B2E2),
    star: Color(0xFFA3D8FF),
    glint: Color(0xFFD7ECFF),
    starPeak: Color(0xFFE2F3FF),
  );

  static const field = CulminaMarkColors(
    background: Color(0xFF000000),
    orbit: Color(0xFF990000),
    inner: Color(0xFF5C0000),
    star: Color(0xFF850000),
    glint: Color(0xFF850000),
    starPeak: Color(0xFFA80000),
  );
}

import 'package:flutter/material.dart';

/// The raw colours behind the three themes. Widgets never read these
/// directly: they use `Theme.of(context).colorScheme` or [AppPalette]
/// (TASK 12.4). The text roles (S5.1) are documented in
/// `docs/DESIGN_SYSTEM.md`: in light and dark every role is WCAG AA
/// (4.5:1) on the background, the surface and the raised surface, and each
/// is at least 1.3 times the next one's contrast. Control borders (S5.2)
/// are at least 3:1 (WCAG 1.4.11); the error colour is AA as text.
class AppColors {
  // The Culmina mark's colours are generated with its geometry
  // (lib/presentation/shared/culmina_mark_geometry.dart, tool/culmina_mark.py).

  // Light Theme
  static const Color lightBackground = Color(0xFFFFFFFF);
  static const Color lightSurface = Color(0xFFF7F7F5);
  static const Color lightSurfaceRaised = Color(0xFFFFFFFF);
  static const Color lightTextPrimary = Color(0xFF37352F); // 11.4:1
  static const Color lightTextSecondary = Color(0xFF5A5955); // 6.5:1
  static const Color lightTextTertiary = Color(0xFF6E6D69); // 4.8:1
  static const Color lightTextDisabled = Color(0xFFA3A29F);
  static const Color lightBorder = Color(0xFFE9E9E7);
  static const Color lightControlBorder = Color(0xFF8F8E8A); // 3.1:1
  static const Color lightError = Color(0xFFB00020); // 6.8:1

  // Dark Theme
  static const Color darkBackground = Color(0xFF191919);
  static const Color darkSurface = Color(0xFF202020);
  static const Color darkSurfaceRaised = Color(0xFF252525);
  static const Color darkTextPrimary = Color(0xFFEBEBEA); // 12.8:1
  static const Color darkTextSecondary = Color(0xFFA5A5A3); // 6.2:1
  static const Color darkTextTertiary = Color(0xFF8F8F8D); // 4.7:1
  static const Color darkTextDisabled = Color(0xFF6B6B69);
  static const Color darkSelection = Color(0xFF343432);
  static const Color darkBorder = Color(0xFF2F2F2F);
  static const Color darkControlBorder = Color(0xFF6F6F6D); // 3.0:1
  static const Color darkError = Color(0xFFF28B82); // 6.4:1

  // Field Mode (Red): brightness, not hue, separates the roles.
  static const Color fieldBackground = Color(0xFF000000);
  static const Color fieldSurface = Color(0xFF110000);
  static const Color fieldSurfaceRaised = Color(0xFF1A0000);
  static const Color fieldTextPrimary = Color(0xFFFF0000);
  static const Color fieldTextSecondary = Color(0xFFAA0000);
  static const Color fieldTextTertiary = Color(0xFF880000);
  static const Color fieldTextDisabled = Color(0xFF660000);
  static const Color fieldBorder = Color(0xFF330000);
  // Brighter than a card border so controls stay visible (UX-39).
  static const Color fieldControlBorder = Color(0xFF880000);
}

import 'package:flutter/material.dart';

/// Approved original Hybrid presentation roles absent from AppPalette.
/// Values: the final computed cascade of the accepted web reference
/// (`design/home-lab` at 86873ce: notion-hybrid.css, hybrid-data-tokens.css,
/// hybrid-refinement.css), Light / Dark / Field. These colours do not supply
/// astronomical intervals or change data semantics.
@immutable
class HybridTokens extends ThemeExtension<HybridTokens> {
  const HybridTokens({
    required this.action,
    required this.onAction,
    required this.selection,
    required this.selectedHourFill,
    required this.selectedHourText,
    required this.selectedHourRule,
    required this.surfaceSubtle,
    required this.surfaceSunken,
    required this.accent,
    required this.success,
    required this.successWash,
    required this.caution,
    required this.cautionWash,
    required this.errorText,
    required this.errorWash,
    required this.hourBackground,
    required this.hourText,
    required this.gainStart,
    required this.gainEnd,
    required this.skyDay,
    required this.skyCivil,
    required this.skyNautical,
    required this.skyAstronomical,
    required this.skyDark,
    required this.moonUp,
    required this.moonFree,
    required this.weatherCaution,
    required this.weatherNotice,
  });

  static const sourceRevision = '86873ce';
  static const fontFamily = 'Geist';
  static const transparent = Color(0x00000000);
  // Exact compact roles in the approved source. Large text uses full week rows.
  static const calendarCaptionSize = 10.0;
  static const navigationLabelSize = 11.0;

  /// Chart tick labels (plan.css `.gain-graph text`, 11 px).
  static const chartLabelSize = 11.0;
  static const minTarget = 48.0;
  static const appBarHeight = 64.0;

  /// Primary action fill (WQA-01: Field `#FF0000` with black text).
  final Color action;

  /// Text on [action].
  final Color onAction;

  /// Selected rows, segments and pressed fills.
  final Color selection;

  /// Weather B hour-axis selection fill (weather-radix.css blue5).
  final Color selectedHourFill;

  /// Text on [selectedHourFill] (blue12; Field retains primary red).
  final Color selectedHourText;

  /// Bottom rule of the selected Weather B hour (blue11).
  final Color selectedHourRule;

  /// Subtle surface: selected navigation, quiet panels.
  final Color surfaceSubtle;

  /// Sunken surface behind raised panels.
  final Color surfaceSunken;

  /// Notion blue: weather icons, main chart lines, links.
  final Color accent;

  /// Saved / Completed text.
  final Color success;

  /// Saved / Completed compact background.
  final Color successWash;

  /// Not saved / Saved · changed / Partly / stale text.
  final Color caution;

  /// Caution compact background.
  final Color cautionWash;

  /// Data error text.
  final Color errorText;

  /// Error compact background.
  final Color errorWash;

  /// Selected weather hour fill.
  final Color hourBackground;

  /// Selected weather hour text.
  final Color hourText;

  /// Stacking-gain gradient start.
  final Color gainStart;

  /// Stacking-gain gradient end.
  final Color gainEnd;

  /// Timeline daylight.
  final Color skyDay;

  /// Timeline civil twilight.
  final Color skyCivil;

  /// Timeline nautical twilight.
  final Color skyNautical;

  /// Timeline astronomical twilight.
  final Color skyAstronomical;

  /// Timeline dark time: black in every theme (owner).
  final Color skyDark;

  /// Moon-above-horizon lane.
  final Color moonUp;

  /// Moon-free dark lane.
  final Color moonFree;

  /// Weather caution (dew, stale).
  final Color weatherCaution;

  /// The Weather page's freshness and gap notices (conditions.css
  /// `--wx-caution`).
  final Color weatherNotice;

  List<Color> get sky => [
    skyDay,
    skyCivil,
    skyNautical,
    skyAstronomical,
    skyDark,
  ];

  static const light = HybridTokens(
    action: Color(0xFF37352F),
    onAction: Color(0xFFFFFFFF),
    selection: Color(0xFFE9E9E7),
    selectedHourFill: Color(0xFFC2E5FF),
    selectedHourText: Color(0xFF113264),
    selectedHourRule: Color(0xFF0D74CE),
    surfaceSubtle: Color(0xFFF7F7F5),
    surfaceSunken: Color(0xFFF0F0ED),
    accent: Color(0xFF0075DE),
    success: Color(0xFF27633D),
    successWash: Color(0xFFE4EEE7),
    caution: Color(0xFF754600),
    cautionWash: Color(0xFFF4ECDF),
    errorText: Color(0xFFB00020),
    errorWash: Color(0xFFF7E7E9),
    hourBackground: Color(0xFFE6F3FE),
    hourText: Color(0xFF005BAB),
    gainStart: Color(0xFF0075DE),
    gainEnd: Color(0xFF005BAB),
    skyDay: Color(0xFFE6F3FE),
    skyCivil: Color(0xFFA6D2F3),
    skyNautical: Color(0xFF599FD5),
    skyAstronomical: Color(0xFF285B90),
    skyDark: Color(0xFF000000),
    moonUp: Color(0xFF607D8B),
    moonFree: Color(0xFF37352F),
    weatherCaution: Color(0xFF754600),
    weatherNotice: Color(0xFF9A5B00),
  );

  static const dark = HybridTokens(
    action: Color(0xFFEBEBEA),
    onAction: Color(0xFF191919),
    selection: Color(0xFF343432),
    selectedHourFill: Color(0xFF004074),
    selectedHourText: Color(0xFFC2E6FF),
    selectedHourRule: Color(0xFF70B8FF),
    surfaceSubtle: Color(0xFF202020),
    surfaceSunken: Color(0xFF141414),
    accent: Color(0xFF62AFF3),
    success: Color(0xFF99C5A6),
    successWash: Color(0xFF2B352E),
    caution: Color(0xFFFFCA70),
    cautionWash: Color(0xFF3B3222),
    errorText: Color(0xFFFF9592),
    errorWash: Color(0xFF3C2929),
    hourBackground: Color(0xFF152D40),
    hourText: Color(0xFFA6D2F3),
    gainStart: Color(0xFF62AFF3),
    gainEnd: Color(0xFFA6D2F3),
    skyDay: Color(0xFFA6D2F3),
    skyCivil: Color(0xFF78B5E5),
    skyNautical: Color(0xFF4388BD),
    skyAstronomical: Color(0xFF244F7A),
    skyDark: Color(0xFF000000),
    moonUp: Color(0xFFB0BEC5),
    moonFree: Color(0xFFEBEBEA),
    weatherCaution: Color(0xFFFFCA70),
    weatherNotice: Color(0xFFFFB74D),
  );

  static const field = HybridTokens(
    action: Color(0xFFFF0000),
    onAction: Color(0xFF000000),
    selection: Color(0xFF330000),
    selectedHourFill: Color(0xFF330000),
    selectedHourText: Color(0xFFFF0000),
    selectedHourRule: Color(0xFFFF0000),
    surfaceSubtle: Color(0xFF110000),
    surfaceSunken: Color(0xFF000000),
    accent: Color(0xFFFF0000),
    success: Color(0xFFFF0000),
    successWash: Color(0xFF110000),
    caution: Color(0xFFFF0000),
    cautionWash: Color(0xFF1A0000),
    errorText: Color(0xFFFF0000),
    errorWash: Color(0xFF1A0000),
    hourBackground: Color(0xFF330000),
    hourText: Color(0xFFFF0000),
    gainStart: Color(0xFF990000),
    gainEnd: Color(0xFFFF0000),
    skyDay: Color(0xFF800000),
    skyCivil: Color(0xFF650000),
    skyNautical: Color(0xFF4D0000),
    skyAstronomical: Color(0xFF340000),
    skyDark: Color(0xFF000000),
    moonUp: Color(0xFFB00000),
    moonFree: Color(0xFFFF0000),
    weatherCaution: Color(0xFFFF0000),
    weatherNotice: Color(0xFFFF0000),
  );

  @override
  HybridTokens copyWith({
    Color? action,
    Color? onAction,
    Color? selection,
    Color? selectedHourFill,
    Color? selectedHourText,
    Color? selectedHourRule,
    Color? surfaceSubtle,
    Color? surfaceSunken,
    Color? accent,
    Color? success,
    Color? successWash,
    Color? caution,
    Color? cautionWash,
    Color? errorText,
    Color? errorWash,
    Color? hourBackground,
    Color? hourText,
    Color? gainStart,
    Color? gainEnd,
    Color? skyDay,
    Color? skyCivil,
    Color? skyNautical,
    Color? skyAstronomical,
    Color? skyDark,
    Color? moonUp,
    Color? moonFree,
    Color? weatherCaution,
    Color? weatherNotice,
  }) => HybridTokens(
    action: action ?? this.action,
    onAction: onAction ?? this.onAction,
    selection: selection ?? this.selection,
    selectedHourFill: selectedHourFill ?? this.selectedHourFill,
    selectedHourText: selectedHourText ?? this.selectedHourText,
    selectedHourRule: selectedHourRule ?? this.selectedHourRule,
    surfaceSubtle: surfaceSubtle ?? this.surfaceSubtle,
    surfaceSunken: surfaceSunken ?? this.surfaceSunken,
    accent: accent ?? this.accent,
    success: success ?? this.success,
    successWash: successWash ?? this.successWash,
    caution: caution ?? this.caution,
    cautionWash: cautionWash ?? this.cautionWash,
    errorText: errorText ?? this.errorText,
    errorWash: errorWash ?? this.errorWash,
    hourBackground: hourBackground ?? this.hourBackground,
    hourText: hourText ?? this.hourText,
    gainStart: gainStart ?? this.gainStart,
    gainEnd: gainEnd ?? this.gainEnd,
    skyDay: skyDay ?? this.skyDay,
    skyCivil: skyCivil ?? this.skyCivil,
    skyNautical: skyNautical ?? this.skyNautical,
    skyAstronomical: skyAstronomical ?? this.skyAstronomical,
    skyDark: skyDark ?? this.skyDark,
    moonUp: moonUp ?? this.moonUp,
    moonFree: moonFree ?? this.moonFree,
    weatherCaution: weatherCaution ?? this.weatherCaution,
    weatherNotice: weatherNotice ?? this.weatherNotice,
  );

  @override
  HybridTokens lerp(covariant HybridTokens? other, double t) {
    if (other == null) return this;
    return HybridTokens(
      action: Color.lerp(action, other.action, t)!,
      onAction: Color.lerp(onAction, other.onAction, t)!,
      selection: Color.lerp(selection, other.selection, t)!,
      selectedHourFill: Color.lerp(
        selectedHourFill,
        other.selectedHourFill,
        t,
      )!,
      selectedHourText: Color.lerp(
        selectedHourText,
        other.selectedHourText,
        t,
      )!,
      selectedHourRule: Color.lerp(
        selectedHourRule,
        other.selectedHourRule,
        t,
      )!,
      surfaceSubtle: Color.lerp(surfaceSubtle, other.surfaceSubtle, t)!,
      surfaceSunken: Color.lerp(surfaceSunken, other.surfaceSunken, t)!,
      accent: Color.lerp(accent, other.accent, t)!,
      success: Color.lerp(success, other.success, t)!,
      successWash: Color.lerp(successWash, other.successWash, t)!,
      caution: Color.lerp(caution, other.caution, t)!,
      cautionWash: Color.lerp(cautionWash, other.cautionWash, t)!,
      errorText: Color.lerp(errorText, other.errorText, t)!,
      errorWash: Color.lerp(errorWash, other.errorWash, t)!,
      hourBackground: Color.lerp(hourBackground, other.hourBackground, t)!,
      hourText: Color.lerp(hourText, other.hourText, t)!,
      gainStart: Color.lerp(gainStart, other.gainStart, t)!,
      gainEnd: Color.lerp(gainEnd, other.gainEnd, t)!,
      skyDay: Color.lerp(skyDay, other.skyDay, t)!,
      skyCivil: Color.lerp(skyCivil, other.skyCivil, t)!,
      skyNautical: Color.lerp(skyNautical, other.skyNautical, t)!,
      skyAstronomical: Color.lerp(skyAstronomical, other.skyAstronomical, t)!,
      skyDark: Color.lerp(skyDark, other.skyDark, t)!,
      moonUp: Color.lerp(moonUp, other.moonUp, t)!,
      moonFree: Color.lerp(moonFree, other.moonFree, t)!,
      weatherCaution: Color.lerp(weatherCaution, other.weatherCaution, t)!,
      weatherNotice: Color.lerp(weatherNotice, other.weatherNotice, t)!,
    );
  }
}

