import 'package:flutter/material.dart';

import '../../core/theme/app_palette.dart';
import '../../core/theme/app_spacing.dart';
import '../../core/theme/app_text_theme.dart';
import '../../core/theme/hybrid_tokens.dart';
import '../../domain/models/session.dart';
import '../../domain/models/session_result.dart';
import 'app_words.dart';
import 'hybrid_icon.dart';

/// A plan's state as the user sees it (S5.4; ADR-019 §3, RD-05, RG-04).
/// The stored statuses stay internal: "Draft" is never shown.
enum PlanState {
  notSaved,
  saved,
  savedChanged,
  tracking,
  completed,

  /// A partial result, recorded through the result form (S8.1–S8.2).
  partly,
  notDone,
  oldLog;

  /// The state the stored fields express: the status, whether the plan was
  /// ever saved (`plannedAtUtc != null`), whether it is a legacy log, and how
  /// a completed result was reported (S8.1). Pure.
  static PlanState from({
    required SessionStatus status,
    required bool savedBefore,
    required bool legacy,
    ResultKind? resultKind,
  }) {
    if (legacy) return oldLog;
    return switch (status) {
      SessionStatus.draft => savedBefore ? savedChanged : notSaved,
      SessionStatus.planned => saved,
      SessionStatus.inProgress => tracking,
      SessionStatus.completed =>
        resultKind == ResultKind.partly ? partly : completed,
      SessionStatus.abandoned => notDone,
    };
  }

  static PlanState of(Session s) => from(
    status: s.status,
    savedBefore: s.plannedAtUtc != null,
    legacy: s.legacy,
    resultKind: s.resultKind,
  );

  /// Current planner facts can be newer than the stored row while autosave
  /// is pending or failed. Only explicit Save plan settles those edits.
  static PlanState forWorkingPlan(
    Session s, {
    required bool hasUnsavedChanges,
  }) {
    final stored = of(s);
    return stored == saved && hasUnsavedChanges ? savedChanged : stored;
  }

  String get word => switch (this) {
    notSaved => AppWords.notSaved,
    saved => AppWords.saved,
    savedChanged => AppWords.savedChanged,
    tracking => AppWords.tracking,
    completed => AppWords.completed,
    partly => AppWords.partly,
    notDone => AppWords.notDone,
    oldLog => AppWords.oldLog,
  };

  /// F19 A1: a result's state carries an icon beside its word (never
  /// colour alone); the others are words only.
  IconData? get icon => switch (this) {
    completed => Icons.check_circle_outline,
    partly => Icons.incomplete_circle_outlined,
    notDone => Icons.cancel_outlined,
    _ => null,
  };

  /// Unsaved work draws attention; a settled plan reads as primary text;
  /// the rest is quiet. A tone, never a verdict.
  Color tone(AppPalette p) => switch (this) {
    notSaved || savedChanged => p.stateUnsaved,
    saved || tracking || completed => p.stateSettled,
    partly || notDone || oldLog => p.stateQuiet,
  };
}

/// The plan-state label (S5.4) as the Hybrid reference's compact status
/// (notion-hybrid.css): Saved, Tracking and Completed in the success role on
/// its wash; Not saved, Saved · changed and Partly in the caution role on
/// its wash (attention, not an error); Not done and Old log quiet on the
/// selection fill. 13 px, padding 3 × 6, radius 4. [withIcon]: Tonight's
/// check (saved) or pencil (unsaved work) mark, 13 px; Plan's label is
/// the word alone at weight 500. It wraps at large text; not tappable.
class PlanStateLabel extends StatelessWidget {
  const PlanStateLabel(this.state, {super.key, this.withIcon = false});

  final PlanState state;
  final bool withIcon;

  @override
  Widget build(BuildContext context) {
    final p = AppPalette.of(context);
    final h = Theme.of(context).extension<HybridTokens>() ?? HybridTokens.light;
    final (fg, bg) = switch (state) {
      PlanState.saved ||
      PlanState.tracking ||
      PlanState.completed => (h.success, h.successWash),
      PlanState.notSaved ||
      PlanState.savedChanged ||
      PlanState.partly => (h.caution, h.cautionWash),
      PlanState.notDone || PlanState.oldLog => (p.textPrimary, h.selection),
    };
    final settled =
        state == PlanState.saved ||
        state == PlanState.tracking ||
        state == PlanState.completed;
    return DecoratedBox(
      decoration: BoxDecoration(
        color: bg,
        borderRadius: BorderRadius.circular(4),
      ),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            if (withIcon) ...[
              HybridIcon(
                settled ? HybridIcons.check : HybridIcons.edit,
                size: MediaQuery.textScalerOf(context).scale(13),
                color: fg,
              ),
              const SizedBox(width: AppSpacing.xs),
            ],
            Flexible(
              child: Text(
                state.word,
                style: AppTextTheme.of(context)
                    .resolve(
                      AppTextTheme.of(context).caption,
                      (withIcon
                          ? AppTextGeometry.timelineDate
                          : AppTextGeometry.standard),
                    )
                    .copyWith(
                      color: fg,
                      fontWeight: withIcon ? FontWeight.w400 : FontWeight.w500,
                    ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

/// A Logbook entry's state (logbook.js `logbook-status-badge`): the state's
/// 16 px mark and its word, 13/500, on the state's wash (padding 3 × 6,
/// radius 4); [due]: Not recorded, the due mark and the word at 400 on the
/// caution wash.
class EntryStateBadge extends StatelessWidget {
  const EntryStateBadge(
    this.state, {
    super.key,
    this.due = false,
    this.large = false,
    this.word,
  });

  /// Not recorded: a saved night that has ended without a result.
  const EntryStateBadge.due({super.key, this.large = false})
    : state = PlanState.saved,
      due = true,
      word = null;

  final PlanState state;
  final bool due;

  /// The entry's header (`.logbook-state-large`): 20/500 with a 22 px mark.
  final bool large;

  /// Words instead of the state's name ("Completed, reported as planned").
  final String? word;

  @override
  Widget build(BuildContext context) {
    final p = AppPalette.of(context);
    final h = Theme.of(context).extension<HybridTokens>() ?? HybridTokens.light;
    final (fg, bg) = due
        ? (h.caution, h.cautionWash)
        : switch (state) {
            PlanState.saved ||
            PlanState.tracking ||
            PlanState.completed => (h.success, h.successWash),
            PlanState.notSaved ||
            PlanState.savedChanged ||
            PlanState.partly => (h.caution, h.cautionWash),
            PlanState.notDone ||
            PlanState.oldLog => (p.textPrimary, h.selection),
          };
    final mark = due
        ? HybridIcons.markDue
        : switch (state) {
            PlanState.completed ||
            PlanState.oldLog => HybridIcons.markCompleted,
            PlanState.partly => HybridIcons.markPartly,
            PlanState.notDone => HybridIcons.markNotDone,
            _ => HybridIcons.markSaved,
          };
    return DecoratedBox(
      decoration: BoxDecoration(
        color: bg,
        borderRadius: BorderRadius.circular(4),
      ),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            HybridIcon(
              mark,
              size: MediaQuery.textScalerOf(context).scale(large ? 22 : 16),
              strokeWidth: 1.7,
              color: fg,
            ),
            const SizedBox(width: AppSpacing.xs),
            Flexible(
              child: Text(
                due ? 'Not recorded' : word ?? state.word,
                semanticsLabel: due ? AppWords.resultNotRecorded : null,
                style: AppTextTheme.of(context)
                    .resolve(
                      (large
                          ? AppTextTheme.of(context).sectionHeading
                          : AppTextTheme.of(context).caption),
                      AppTextGeometry.badge,
                    )
                    .copyWith(
                      color: fg,
                      fontWeight: due ? FontWeight.w400 : FontWeight.w500,
                    ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

import '../../core/theme/app_text_theme.dart';

import 'package:flutter/material.dart';

import '../../core/theme/app_palette.dart';
import '../../core/theme/app_spacing.dart';
import '../../core/utils/quantity_text.dart';
import '../../domain/services/fit_analyzer.dart';
import 'app_words.dart';
import 'night_text.dart';

/// The answer first (S5.4; ADR-019 §6, addendum §3.1–§3.2): the verdict
/// headline in its status colour ("Fits: 2 h 5 min needed of 4 h 20 min
/// usable"), its reason, optional key numbers and an optional action (fill
/// or trim). It calculates nothing: the state, the durations, the reason
/// and the key numbers come from the ViewModel (the fit analysis); values
/// are formatted with `QuantityText`.
class StatusBlock extends StatelessWidget {
  const StatusBlock({
    super.key,
    required this.state,
    this.needed,
    this.usable,
    this.reason,
    this.missing,
    this.keyNumbers = const [],
    this.action,
    this.separateFigures = false,
    this.headingStyle,
    this.figuresBeforeReason,
    this.fitLine = false,
  });

  /// Tonight's Hybrid fit line (app.js `.fit-line`, `.plan-reason`): a
  /// check (or an info mark for a missing input) beside a 13 px verdict, the
  /// reason in 14 px secondary below it.
  final bool fitLine;

  final FitState state;

  /// Time needed and usable time; the headline names them only when both
  /// are known (unknown stays unknown).
  final Duration? needed;
  final Duration? usable;

  final String? reason;

  /// For a missing input: [AppWords.needsTarget] (the default) or another
  /// glossary word the adopting screen chooses.
  final String? missing;

  /// Label and already formatted value pairs, e.g. ("Capture ends",
  /// "01:40").
  final List<(String, String)> keyNumbers;

  final Widget? action;

  /// Hybrid shows the verdict, then labelled measurements rather than a
  /// sentence that repeats both values in the heading.
  final bool separateFigures;
  final TextStyle? headingStyle;

  /// Plan shows figures before its explanation; Tonight retains its summary
  /// reason above them. Existing sentence-headline adopters keep their order.
  final bool? figuresBeforeReason;

  /// The headline in the glossary's words (RD-14). Pure.
  static String headline(
    FitState state, {
    Duration? needed,
    Duration? usable,
    String? missing,
  }) {
    String measured(String word) => needed == null || usable == null
        ? word
        : AppWords.headline(
            word,
            QuantityText.budgetDuration(needed),
            QuantityText.budgetDuration(usable),
          );
    return switch (state) {
      FitState.fits => measured(AppWords.fits),
      FitState.tight => measured(AppWords.tight),
      FitState.doesNotFit => measured(AppWords.doesNotFit),
      FitState.noWindow => AppWords.noWindow,
      FitState.needsInput => missing ?? AppWords.needsTarget,
      FitState.nothingToFit => AppWords.needsBlock,
    };
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final p = AppPalette.of(context);
    final text = theme.textTheme;
    final figures = [
      if (separateFigures && needed != null)
        ('Needed in imaging window', QuantityText.budgetDuration(needed!)),
      if (separateFigures && usable != null)
        ('Usable', QuantityText.budgetDuration(usable!)),
      ...keyNumbers,
    ];
    final figuresFirst = figuresBeforeReason ?? separateFigures;
    final explanation = Text(
      reason ?? '',
      style: fitLine
          ? AppTextTheme.of(context)
                .resolve(text.bodySmall, AppTextGeometry.fitExplanation)
                .copyWith(color: p.textSecondary)
          : text.bodyMedium?.copyWith(color: p.textSecondary),
    );
    final verdictStyle =
        (fitLine
                ? AppTextTheme.of(context)
                      .resolve(text.bodySmall, AppTextGeometry.fitVerdict)
                      .copyWith(fontWeight: FontWeight.w500)
                : (headingStyle ?? text.titleMedium))
            ?.copyWith(color: FitText.color(state, theme.colorScheme, p));
    final verdict = Text(
      headline(
        state,
        needed: separateFigures ? null : needed,
        usable: separateFigures ? null : usable,
        missing: missing,
      ),
      key: const Key('status.headline'),
      style: verdictStyle,
    );
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Semantics(
          header: true,
          child: fitLine
              ? Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Padding(
                      padding: const EdgeInsets.only(top: 1, right: 7),
                      child: Icon(
                        state == FitState.needsInput ||
                                state == FitState.nothingToFit
                            ? Icons.info_outline
                            : state == FitState.fits || state == FitState.tight
                            ? Icons.check
                            : Icons.close,
                        // 17 px at 100 %, growing with the text it marks.
                        size: MediaQuery.textScalerOf(context).scale(17),
                        color: verdictStyle?.color,
                      ),
                    ),
                    Expanded(child: verdict),
                  ],
                )
              : verdict,
        ),
        if (reason != null && !figuresFirst) ...[
          // Hybrid fit line: the reason 6 below the verdict.
          SizedBox(height: fitLine ? 6 : AppSpacing.xs),
          explanation,
        ],
        if (figures.isNotEmpty) ...[
          const SizedBox(height: AppSpacing.md),
          // S6.16: each number as a label above its value, so the answer's
          // figures read as a set (the scale's caption and group roles).
          Wrap(
            spacing: AppSpacing.lg,
            runSpacing: AppSpacing.sm,
            children: [
              for (final (label, value) in figures)
                MergeSemantics(
                  child: Column(
                    key: Key('status.number.$label'),
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        label,
                        // Hybrid `.plan-measures dt`: 13 at normal leading.
                        style:
                            (fitLine
                                    ? AppTextTheme.of(context).resolve(
                                        text.bodySmall,
                                        AppTextGeometry.fitMeasure,
                                      )
                                    : text.bodySmall)
                                ?.copyWith(color: p.textTertiary),
                      ),
                      if (fitLine) const SizedBox(height: AppSpacing.xs),
                      Text(
                        value,
                        style: fitLine
                            ? AppTextTheme.of(context)
                                  .resolve(
                                    text.bodyMedium,
                                    AppTextGeometry.fitValue,
                                  )
                                  .copyWith(
                                    color: p.textPrimary,
                                    fontWeight: FontWeight.w500,
                                    fontFeatures: const [
                                      FontFeature.tabularFigures(),
                                    ],
                                  )
                            : text.titleSmall?.copyWith(color: p.textPrimary),
                      ),
                    ],
                  ),
                ),
            ],
          ),
        ],
        if (reason != null && figuresFirst) ...[
          const SizedBox(height: AppSpacing.sm),
          explanation,
        ],
        if (action != null) ...[const SizedBox(height: AppSpacing.md), action!],
      ],
    );
  }
}

import 'package:flutter/material.dart';
import 'package:provider/provider.dart';

import '../../core/theme/app_motion.dart';
import '../../core/theme/app_palette.dart';
import '../../core/theme/app_spacing.dart';
import '../../core/theme/app_text_theme.dart';
import 'hybrid_icon.dart';
import 'hybrid_quiet_ink.dart';
import '../viewmodels/disclosure_viewmodel.dart';

/// Detail one tap away (S5.5; ADR-019 §7, RD-06, RG-06): a header with the
/// section's title and a factual summary, and the content below it when
/// open. The open or closed state is remembered per [sectionKey]
/// ([DisclosureViewModel]).
///
/// The [summary] states facts ("3 lines · 2 h 35 min total"), never a
/// verdict ("good", "fine"); the verdict belongs to the status block. The
/// summary stays visible when the section is open.
class CollapsibleSection extends StatelessWidget {
  const CollapsibleSection({
    super.key,
    required this.sectionKey,
    required this.title,
    required this.child,
    this.summary,
    this.initiallyOpen = false,
    this.open,
    this.onToggle,
    this.topRule = true,
    this.titleStyle,
    this.icon,
    this.iconColor,
    this.readableFeedback = false,
  });

  /// A data icon before the title (conditions.css `.condition-data-heading`:
  /// 20 px, 10 before the words), e.g. the Moon or the Sun.
  final HybridIconData? icon;
  final Color? iconColor;

  /// Local opt-in for confirmed quiet-label interaction states.
  final bool readableFeedback;

  /// The Hybrid disclosure's thin rule above it (`.plan-disclosure`).
  final bool topRule;

  /// A nested disclosure's smaller title (Library 15/600); defaults to the
  /// section heading role 20/600.
  final TextStyle? titleStyle;

  /// Stable and unique, e.g. `planner.budgetDetails`; it names the stored
  /// preference, so never rename one without a reason.
  final String sectionKey;
  final String title;
  final String? summary;
  final Widget child;

  /// The state before the user has opened or closed it.
  final bool initiallyOpen;

  /// Controlled use (S7.6): the caller holds the state, e.g. a dialog whose
  /// section need not be remembered. With both set, the section reads no
  /// [DisclosureViewModel] and [initiallyOpen] is unused.
  final bool? open;
  final VoidCallback? onToggle;

  @override
  Widget build(BuildContext context) {
    final controlled = this.open != null && onToggle != null;
    final vm = controlled ? null : context.watch<DisclosureViewModel>();
    final open =
        this.open ?? vm!.isOpen(sectionKey, initiallyOpen: initiallyOpen);
    final p = AppPalette.of(context);
    void toggle() => controlled ? onToggle!() : vm!.setOpen(sectionKey, !open);
    final resize = AppMotion.duration(context, AppMotion.medium);
    final Widget body = open
        ? Padding(
            padding: const EdgeInsets.only(bottom: AppSpacing.sm),
            child: child,
          )
        : const SizedBox(width: double.infinity);

    // The Hybrid disclosure (hybrid-refinement.css `.plan-disclosure`):
    // grid title | chevron, gap 16, min 48, padding 6 0; title 20/600 at
    // 1.4; caption 13 at 1.4, 2 below; an 18 px chevron (m9 5 7 7-7 7,
    // stroke 1.7) turned down when closed and up when open (120 ms).
    final header = Semantics(
      key: Key('section.$sectionKey'),
      button: true,
      enabled: true,
      expanded: open,
      onTap: toggle,
      hint: open ? 'Collapse' : 'Expand',
      excludeSemantics: true,
      label: [title, ?summary].join(', '),
      child: InkWell(
        overlayColor: readableFeedback ? HybridQuietInk.overlay(context) : null,
        onTap: toggle,
        child: ConstrainedBox(
          constraints: const BoxConstraints(minHeight: 48),
          child: Padding(
            padding: const EdgeInsets.symmetric(vertical: 6),
            child: Row(
              children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          if (icon case final i?) ...[
                            HybridIcon(
                              i,
                              size: 20,
                              strokeWidth: 1.7,
                              color: iconColor ?? p.textPrimary,
                            ),
                            const SizedBox(width: 10),
                          ],
                          Flexible(
                            child: Text(
                              title,
                              style:
                                  (titleStyle ??
                                          AppTextTheme.of(context).resolve(
                                            AppTextTheme.of(context)
                                                .sectionHeading,
                                            AppTextGeometry.badge,
                                          ))
                                      .copyWith(color: p.textPrimary),
                            ),
                          ),
                        ],
                      ),
                      if (summary != null)
                        Padding(
                          padding: const EdgeInsets.only(top: 2),
                          child: Text(
                            summary!,
                            style: AppTextTheme.of(context)
                                .resolve(
                                  AppTextTheme.of(context).caption,
                                  AppTextGeometry.compact,
                                )
                                .copyWith(color: p.textSecondary),
                          ),
                        ),
                    ],
                  ),
                ),
                const SizedBox(width: AppSpacing.md),
                AnimatedRotation(
                  turns: open ? -0.25 : 0.25,
                  duration: AppMotion.duration(context, AppMotion.short),
                  curve: AppMotion.curve,
                  child: HybridIcon(
                    HybridIcons.chevron,
                    size: 18,
                    color: p.textSecondary,
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        if (topRule)
          DecoratedBox(
            decoration: BoxDecoration(
              border: Border(top: BorderSide(color: p.border)),
            ),
            child: header,
          )
        else
          header,
        // Reduced motion: no AnimatedSize at all (with a zero duration it
        // throws a layout assertion).
        if (resize == Duration.zero)
          body
        else
          ClipRect(
            child: AnimatedSize(
              duration: resize,
              curve: AppMotion.curve,
              alignment: Alignment.topCenter,
              child: body,
            ),
          ),
      ],
    );
  }
}

