/// "Ljubljana ▾  Fri, Nov 14 ▾" (S5.6; ADR-019 §5, §6; addendum §3.1–§3.2):
/// the one control that says which site and night a screen describes, for
/// Tonight and the planner. Each part is its own 48 dp target that reports
/// a tap; what choosing does (the site picker, or changing the plan's
/// night, UX-11) is the adopting screen's (P6.3, P6.6).
///
/// Below it, once, the zone rule (trap 2): times are in the site's zone, or
/// labelled as the device zone when the site has none. Without a site there
/// is no night (ADR-007 §9), so only the site part shows.
///
/// S6.16: [framed] sets it on a card, so the site and night read as one
/// deliberate context area (Tonight and the planner); each part leads with
/// its icon (a place, a date).
class ContextLine extends StatelessWidget {
  const ContextLine({
    super.key,
    required this.siteName,
    this.noSiteLabel = noSite,
    required this.night,
    required this.onSite,
    required this.onNight,
    this.zoneId,
    this.nightStartUtc,
    this.framed = false,
    this.compact = false,
    this.siteDescription,
  });

  /// Null when no site is set.
  final String? siteName;

  /// What the site chip says without a site.
  final String noSiteLabel;

  /// The night's evening date; null without a site.
  final CalendarDate? night;

  final VoidCallback onSite;
  final VoidCallback onNight;

  /// The site's IANA zone, if it has one.
  final String? zoneId;

  /// When the night starts, for the zone caption's offset; no caption
  /// without it.
  final DateTime? nightStartUtc;

  /// On a card (S6.16).
  final bool framed;

  /// Tonight keeps place and date on one line; full values remain accessible.
  final bool compact;
  final String? siteDescription;

  /// Shown instead of a site name when none is set.
  static const noSite = 'No site set';

  /// Home's site chip without a site (app.js `app-context`): the action.
  static const setSite = 'Set site';

  /// "Times in site zone Europe/Ljubljana, CET, UTC+01:00", or the device
  /// zone's caption when the site has no zone. Pure formatting.
  static String zoneRule(DateTime nightStartUtc, {String? zoneId}) =>
      'Times in ${NightTimeFormatter.zoneCaption(nightStartUtc, zoneId: zoneId)}';

  @override
  Widget build(BuildContext context) {
    final p = AppPalette.of(context);
    final text = Theme.of(context).textTheme;
    final nightText = night == null
        ? null
        : 'Night of ${NightTimeFormatter.eveningDate(night!)}';
    final line = Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        if (compact)
          Row(
            children: [
              Flexible(
                child: _Choice(
                  key: const Key('context.site'),
                  icon: HybridIcons.homePin,
                  text: siteName ?? noSiteLabel,
                  semanticsLabel:
                      '${AppWords.site}: ${siteDescription ?? siteName ?? noSite}',
                  hint: 'Choose a site',
                  singleLine: true,
                  onTap: onSite,
                ),
              ),
              if (night != null) ...[
                const SizedBox(width: AppSpacing.xs),
                _Choice(
                  key: const Key('context.night'),
                  icon: HybridIcons.planner,
                  text: NightTimeFormatter.eveningDate(night!),
                  semanticsLabel: nightText!,
                  hint: 'Choose a night',
                  singleLine: true,
                  onTap: onNight,
                ),
              ],
            ],
          )
        else
          Wrap(
            spacing: AppSpacing.xs,
            crossAxisAlignment: WrapCrossAlignment.center,
            children: [
              _Choice(
                key: const Key('context.site'),
                icon: HybridIcons.homePin,
                text: siteName ?? noSiteLabel,
                semanticsLabel: '${AppWords.site}: ${siteName ?? noSite}',
                hint: 'Choose a site',
                onTap: onSite,
              ),
              if (nightText != null)
                _Choice(
                  key: const Key('context.night'),
                  icon: HybridIcons.planner,
                  text: nightText,
                  semanticsLabel: nightText,
                  hint: 'Choose a night',
                  onTap: onNight,
                ),
            ],
          ),
        if (night != null && nightStartUtc != null)
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: AppSpacing.xs),
            child: Text(
              zoneRule(nightStartUtc!, zoneId: zoneId),
              key: const Key('context.zone'),
              style: text.bodySmall?.copyWith(color: p.textTertiary),
            ),
          ),
      ],
    );
    if (!framed) return line;
    return Card(
      key: const Key('context.card'),
      margin: const EdgeInsets.only(bottom: AppSpacing.md),
      child: Padding(
        padding: const EdgeInsets.fromLTRB(
          AppSpacing.sm,
          AppSpacing.xs,
          AppSpacing.md,
          AppSpacing.sm,
        ),
        child: line,
      ),
    );
  }
}

/// One part of the line: its value and a ▾, a 48 dp button.
class _Choice extends StatelessWidget {
  const _Choice({
    super.key,
    required this.icon,
    required this.text,
    required this.semanticsLabel,
    required this.hint,
    required this.onTap,
    this.singleLine = false,
  });

  final bool singleLine;
  final HybridIconData icon;
  final String text;
  final String semanticsLabel;
  final String hint;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    final p = AppPalette.of(context);
    return Semantics(
      button: true,
      enabled: true,
      onTap: onTap,
      label: semanticsLabel,
      hint: hint,
      excludeSemantics: true,
      child: Tooltip(
        message: semanticsLabel,
        excludeFromSemantics: true,
        child: InkWell(
          onTap: onTap,
          child: ConstrainedBox(
            constraints: const BoxConstraints(minHeight: 48, minWidth: 48),
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: AppSpacing.xs),
              // styles.css `.app-context button`: a 13 px mark, 5 apart, the
              // 13 px value and a 13 px down chevron, all in the text colour.
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  HybridIcon(icon, size: 13, color: p.textPrimary),
                  const SizedBox(width: 5),
                  Flexible(
                    child: Text(
                      text,
                      maxLines: singleLine ? 1 : null,
                      overflow: singleLine ? TextOverflow.ellipsis : null,
                      style: AppTextTheme.of(context).caption
                          .copyWith(color: p.textPrimary),
                    ),
                  ),
                  const SizedBox(width: 5),
                  HybridIcon(HybridIcons.down, size: 13, color: p.textPrimary),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}

/// The shared night picker (S5.6): the date picker in the app's theme (red
/// in field mode), from a year ago to five years ahead as the planner's
/// picker allows, starting at [initial] (else [today]). Returns the chosen
/// evening, or null when cancelled.
Future<CalendarDate?> pickNight(
  BuildContext context, {
  CalendarDate? initial,
  DateTime? today,
  TransitionBuilder? builder,
}) async {
  final now = today ?? DateTime.now();
  final picked = await showDialog<DateTime>(
    context: context,
    builder: (context) {
      final dialog = NightPickerDialog(
        initialDate: initial == null
            ? DateUtils.dateOnly(now)
            : DateTime(initial.year, initial.month, initial.day),
        firstDate: DateTime(now.year - 1, now.month, now.day),
        lastDate: DateTime(now.year + 5, now.month, now.day),
      );
      return builder?.call(context, dialog) ?? dialog;
    },
  );
  return picked == null ? null : CalendarDate.fromDateTimeFields(picked);
}

import 'package:flutter/material.dart';

import '../../core/theme/app_spacing.dart';
import '../../core/theme/hybrid_tokens.dart';

/// What the user chose when unsaved changes would be left behind.
enum UnsavedChoice { save, discard, cancel }

/// The three-way prompt (S5.8; ADR-019 §3, addendum §3.3): "[plan] has
/// changes that are not saved." with Cancel · Discard · Save. Dismissing
/// it (back, a tap outside) is Cancel, so nothing is lost by accident.
/// What Save and Discard then do belongs to the caller (P6.1); this is the
/// prompt only. Discard is styled as destructive.
///
/// [library]: a Library editor's prompt (library.js `cancelEdit`): "Your
/// changes to “[plan]” are not saved.", Cancel and Discard side by side,
/// then Save the full width.
Future<UnsavedChoice> askUnsavedChanges(
  BuildContext context, {
  required String plan,
  String message = '',
  String saveLabel = 'Save and leave',
  bool library = false,
}) async {
  Widget cancel(BuildContext context) => OutlinedButton(
    key: const Key('unsaved.cancel'),
    onPressed: () => Navigator.pop(context, UnsavedChoice.cancel),
    child: const Text('Cancel'),
  );
  Widget discard(BuildContext context) => OutlinedButton(
    key: const Key('unsaved.discard'),
    onPressed: () => Navigator.pop(context, UnsavedChoice.discard),
    child: const Text('Discard'),
  );
  Widget save(BuildContext context, String label) => FilledButton(
    key: const Key('unsaved.save'),
    onPressed: () => Navigator.pop(context, UnsavedChoice.save),
    child: Text(label),
  );
  final choice = await showDialog<UnsavedChoice>(
    context: context,
    builder: (context) => AlertDialog(
      title: const Text('Unsaved changes'),
      content: Text(
        message.isNotEmpty
            ? message
            : library
            ? 'Your changes to “$plan” are not saved.'
            : '"$plan" has changes that are not saved.',
      ),
      // plan.html `#leave-plan`: Cancel and Discard outlined, the save
      // filled, in one row that wraps from the end, 8 apart
      // (`.leave-actions`): at a phone's width the save goes below (QA-05;
      // the dialog's own overflow bar stacked all three).
      actions: library
          ? [
              _WideActions(
                children: [
                  Row(
                    spacing: AppSpacing.sm,
                    children: [
                      Expanded(child: cancel(context)),
                      Expanded(child: discard(context)),
                    ],
                  ),
                  save(context, 'Save'),
                ],
              ),
            ]
          : [
              SizedBox(
                width: double.infinity,
                child: Wrap(
                  alignment: WrapAlignment.end,
                  spacing: AppSpacing.sm,
                  runSpacing: AppSpacing.sm,
                  children: [
                    cancel(context),
                    discard(context),
                    save(context, saveLabel),
                  ],
                ),
              ),
            ],
    ),
  );
  return choice ?? UnsavedChoice.cancel;
}

/// A dialog's actions the full width of the dialog, stacked 8 apart
/// (hybrid-refinement.css `.workspace-actions` in a dialog).
class _WideActions extends StatelessWidget {
  const _WideActions({required this.children});

  final List<Widget> children;

  @override
  Widget build(BuildContext context) => SizedBox(
    width: double.infinity,
    child: Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      spacing: AppSpacing.sm,
      children: children,
    ),
  );
}

/// "Discard this edit?" (plan.html `#discard-edit`): an editor's unapplied
/// fields; the draft keeps what was already applied. True only for
/// Discard edit; Keep editing, Back and a tap outside keep the editor.
Future<bool> askDiscardEdit(BuildContext context) async {
  final discard = await showDialog<bool>(
    context: context,
    builder: (context) => AlertDialog(
      title: const Text('Discard this edit?'),
      content: const Text(
        'Unapplied fields in this editor will be discarded. Changes you '
        'already applied to the draft remain.',
      ),
      actions: [
        OutlinedButton(
          key: const Key('discardEdit.keep'),
          onPressed: () => Navigator.pop(context, false),
          child: const Text('Keep editing'),
        ),
        FilledButton(
          key: const Key('discardEdit.discard'),
          onPressed: () => Navigator.pop(context, true),
          child: const Text('Discard edit'),
        ),
      ],
    ),
  );
  return discard ?? false;
}

/// The one confirmation for a destructive action on something stored
/// (S5.8; RD-09 = M): deleting a rig, a target, a site or a Logbook entry,
/// Abandon, Restore. [title] names the item ("Delete rig "Refractor
/// 400"?"), [message] says the consequence ("Plans that use it keep their
/// saved values."), [action] is the verb on the destructive button
/// ("Delete"). True only when the user taps [action]: Cancel, back and a
/// tap outside all keep the item. Edits inside a plan use the undo message
/// instead (`showUndo`).
Future<bool> confirmDestructive(
  BuildContext context, {
  required String title,
  required String message,
  String action = 'Delete',
}) async {
  final confirmed = await showDialog<bool>(
    context: context,
    builder: (context) => AlertDialog(
      title: Text(title),
      content: Text(message),
      // library.js / logbook.js `choiceDialog`: Cancel and the destructive
      // action side by side, the action outlined in the error colour.
      actions: [
        _WideActions(
          children: [
            Row(
              spacing: AppSpacing.sm,
              children: [
                Expanded(
                  child: OutlinedButton(
                    key: const Key('confirm.cancel'),
                    onPressed: () => Navigator.pop(context, false),
                    child: const Text('Cancel'),
                  ),
                ),
                Expanded(
                  child: OutlinedButton(
                    key: const Key('confirm.action'),
                    onPressed: () => Navigator.pop(context, true),
                    style: OutlinedButton.styleFrom(
                      foregroundColor:
                          (Theme.of(context).extension<HybridTokens>() ??
                                  HybridTokens.light)
                              .errorText,
                    ),
                    child: Text(action),
                  ),
                ),
              ],
            ),
          ],
        ),
      ],
    ),
  );
  return confirmed ?? false;
}

import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';

import '../../core/config/feature_scope.dart';
import '../../core/theme/app_palette.dart';
import '../../core/theme/hybrid_tokens.dart';
import '../../core/theme/hybrid_view_entrance.dart';
import '../shared/app_words.dart';
import '../shared/hybrid_icon.dart';
import '../../core/theme/app_text_theme.dart';

/// The bottom-navigation shell of ADR-015 (TASK 12.2): Tonight · Logbook ·
/// Library · Settings, one navigator per tab.
///
/// Back (ADR-015 §3): pops within the current tab first (go_router); at a
/// tab's root it returns to Tonight; at Tonight's root it leaves the app.
class AppShell extends StatelessWidget {
  const AppShell({
    super.key,
    required this.navigationShell,
    this.showNavigation = true,
  });

  final StatefulNavigationShell navigationShell;
  final bool showNavigation;

  /// The root navigation bar (for tests and the host renders).
  static const navigationKey = Key('app.navigation');

  /// The four roots with the reference's line icons (workspace.js `paths`).
  static List<({HybridIconData icon, String label})> get items => [
    (icon: HybridIcons.moon, label: 'Tonight'),
    if (FeatureScope.logbook)
      (icon: HybridIcons.book, label: AppWords.logbook), // S8.5 (RD-14)
    (icon: HybridIcons.library, label: 'Library'),
    (icon: HybridIcons.settings, label: 'Settings'),
  ];

  /// Kept for callers that list the destinations' labels.
  static List<NavigationDestination> get destinations => [
    for (final i in items)
      NavigationDestination(icon: HybridIcon(i.icon), label: i.label),
  ];

  @override
  Widget build(BuildContext context) {
    final onTonight = navigationShell.currentIndex == 0;
    void select(int i) => navigationShell.goBranch(
      i,
      initialLocation: i == navigationShell.currentIndex,
    );
    final largeText = MediaQuery.textScalerOf(context).scale(1) >= 1.5;
    final theme = Theme.of(context);
    final palette = AppPalette.of(context);
    final hybrid = theme.extension<HybridTokens>() ?? HybridTokens.light;
    // workspace.css `.app-nav` (Hybrid): a subtle top rule, padding 8 4,
    // four equal 56 px buttons 2 apart; the selected one on the subtle
    // surface (radius 6) in 600 primary, the others 400 secondary; a 19 px
    // icon 5 above the 11 px Geist label. At large text, two per row.
    Widget button(int i) {
      final selected = i == navigationShell.currentIndex;
      final color = selected ? palette.textPrimary : palette.textSecondary;
      final item = items[i];
      return Semantics(
        selected: selected,
        button: true,
        label: item.label,
        excludeSemantics: true,
        enabled: true,
        onTap: () => select(i),
        child: Material(
          color: selected ? hybrid.surfaceSubtle : HybridTokens.transparent,
          borderRadius: BorderRadius.circular(6),
          child: InkWell(
            key: Key('nav.${item.label.toLowerCase()}'),
            borderRadius: BorderRadius.circular(6),
            onTap: () => select(i),
            child: ConstrainedBox(
              constraints: const BoxConstraints(minHeight: 56),
              child: Padding(
                padding: const EdgeInsets.all(4),
                child: Center(
                  child: Wrap(
                    direction: largeText ? Axis.horizontal : Axis.vertical,
                    alignment: WrapAlignment.center,
                    crossAxisAlignment: WrapCrossAlignment.center,
                    spacing: largeText ? 8 : 5,
                    children: [
                      HybridIcon(
                        item.icon,
                        size: MediaQuery.textScalerOf(context).scale(19),
                        color: color,
                      ),
                      Text(
                        item.label,
                        textAlign: TextAlign.center,
                        style: AppTextTheme.of(context).navigationLabel
                            .copyWith(
                              color: color,
                              fontWeight: selected
                                  ? FontWeight.w600
                                  : FontWeight.w400,
                            ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
        ),
      );
    }

    final perRow = largeText ? 2 : items.length;
    return PopScope(
      canPop: onTonight,
      onPopInvokedWithResult: (didPop, _) {
        if (!didPop) navigationShell.goBranch(0);
      },
      child: Scaffold(
        body: HybridViewEntrance(
          trigger: navigationShell.currentIndex,
          child: navigationShell,
        ),
        bottomNavigationBar: !showNavigation
            ? null
            : DecoratedBox(
                key: navigationKey,
                decoration: BoxDecoration(
                  color: theme.scaffoldBackgroundColor,
                  border: Border(top: BorderSide(color: palette.border)),
                ),
                child: SafeArea(
                  top: false,
                  child: Padding(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 4,
                      vertical: 8,
                    ),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        for (var row = 0; row < items.length; row += perRow)
                          Padding(
                            padding: EdgeInsets.only(top: row == 0 ? 0 : 2),
                            child: Row(
                              children: [
                                for (
                                  var i = row;
                                  i < row + perRow && i < items.length;
                                  i++
                                ) ...[
                                  if (i > row) const SizedBox(width: 2),
                                  Expanded(child: button(i)),
                                ],
                              ],
                            ),
                          ),
                      ],
                    ),
                  ),
                ),
              ),
      ),
    );
  }
}
